def raycast_fill(grid, center_cells):
    """
    From each center, cast rays in 4 directions.
    Fill cells along ray until hitting 3 or other center, or fill from other centers.
    3s in input stay as 3 in output.
    """
    grid = [row[:] for row in grid]

    # Store original 3 positions as blockers
    blockers = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 3:
                blockers.add((r, c))

    # For each center, trace rays in 4 directions
    for r, c, val in center_cells:
        # Trace up
        for nr in range(r - 1, -1, -1):
            if (nr, c) in blockers:
                break  # 3 blocks
            if 0 <= nr < len(grid) and 0 <= c < len(grid[0]):
                grid[nr][c] = val

        # Trace down
        for nr in range(r + 1, len(grid)):
            if (nr, c) in blockers:
                break
            if nr < len(grid) and c < len(grid[0]):
                grid[nr][c] = val

        # Trace left
        for nc in range(c - 1, -1, -1):
            if (r, nc) in blockers:
                break
            if r < len(grid) and nc < len(grid[0]):
                grid[r][nc] = val

        # Trace right
        for nc in range(c + 1, len(grid[0])):
            if (r, nc) in blockers:
                break
            if r < len(grid) and nc < len(grid[0]):
                grid[r][nc] = val

    return grid

