def fill_with_pass_through_grids(grid):
    """
    Fill in order (reading order centers), passes through filled cells from other centers,
    but writes to the grid. Later fills overwrite earlier fills.
    3s are transparent (pass through, don't write).
    Stops at grid edge.
    """
    import copy
    grid = copy.deepcopy(grid)

    centers = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val not in (0, 3):
                centers.append((r, c, val))

    for r, c, val in centers:
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            while 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                cell = grid[nr][nc]
                if cell == 3:
                    # Skip 3s
                    nr += dr
                    nc += dc
                    continue
                if cell == 0 or cell != val:
                    # Fill 0s or overwrite different fills
                    grid[nr][nc] = val
                    nr += dr
                    nc += dc
                else:
                    # Same fill value, stop or bypass
                    nr += dr
                    nc += dc
    return grid

